        const profile = this.profiles.find((item) => item.id === id);
        if (!profile)
          throw new Error("Instrument profile not found.");
        const endpoint = profile.state.transport === "serial" ? { kind: "serial", settings: { ...profile.state.serial } } : { kind: "visa", settings: { ...profile.state.visa } };
        const device = await (0, qpmDeviceRegistry_12.pickOrCreateDevice)(this.devices, "Promote instrument profile to QPM device", profile.name);
        if (!device)
          return;
        await this.devices.upsertEndpoint(device.id, endpoint);
